SELECT capability.*, ( SELECT COUNT(1) FROM ai_agent_resource_user_grant grant_record WHERE grant_record.resource_type = 'CAPABILITY' AND grant_record.resource_id = capability.id ) AS access_user_count FROM ai_capability_definition capability
and (capability.capability_name like CONCAT('%', #{keyword}, '%') or capability.capability_code like CONCAT('%', #{keyword}, '%') or capability.description like CONCAT('%', #{keyword}, '%'))
and capability.`domain` = #{domain}
and capability.enabled = #{enabled}
order by capability.updated_at desc

SELECT * FROM ai_capability_definition WHERE capability_code IN
#{code}
ORDER BY id desc FOR UPDATE
